import type { EngineBracket, EngineMatch } from '../types';
import { cascadeForward } from './cascade-utils';

export function cascadeUndo(bracket: EngineBracket, matchId: string): EngineBracket {
  const matches = cloneMatches(bracket.matches);

  const match = matches.find((m) => m.id === matchId);
  if (!match?.winner) return { ...bracket, matches };

  const oldWinner = match.winner;
  match.winner = null;

  cascadeForward(matches, matchId, oldWinner);

  return { ...bracket, matches };
}

function cloneMatches(matches: readonly EngineMatch[]): EngineMatch[] {
  return matches.map((m) => ({
    ...m,
    competitorA: m.competitorA ? { ...m.competitorA } : null,
    competitorB: m.competitorB ? { ...m.competitorB } : null,
    winner: m.winner ? { ...m.winner } : null,
  }));
}
